INSERT INTO `news` (title, post) VALUES ('Atualização - gladCode 2.9.3', '<div>A gladCode foi atualizada para a versão 2.9.3.</div>\r\n<div>Confira abaixo a lista de mudanças:</div>\r\n<div>&nbsp;</div>\r\n<div><strong>Balanceamento</strong></div>\r\n<ul>\r\n<li>\r\n<div>A habilidade <a href="https://gladcode.dev/function/teleport" rev="en_rl_none">teleport</a> teve seu alcance máximo reduzido de 5p + 1p por ponto de Poder Mágico para <strong>5p + 0.8p</strong> por ponto de Poder Mágico. <em>Motivo: o alcance do teleporte estava permitindo reposicionamentos longos demais, e gladiadores que usam teleport seguem com taxas de vitória acima da média.</em></div>\r\n</li>\r\n<li>\r\n<div>A habilidade <a href="https://gladcode.dev/function/fireball" rev="en_rl_none">fireball</a> teve seu custo reduzido de 50 para <strong>40 ap</strong>. <em>Motivo: a taxa de vitórias da fireball está abaixo da média; o custo menor deve dar mais presença à habilidade nas batalhas.</em></div>\r\n</li>\r\n<li>\r\n<div>A habilidade <a href="https://gladcode.dev/function/block" rev="en_rl_none">block</a> teve sua duração reduzida de 7 para <strong>5 segundos</strong>. <em>Motivo: pelo seu custo, a proteção estava anulando dano por tempo demais.</em></div>\r\n</li>\r\n<li>\r\n<div>A habilidade <a href="https://gladcode.dev/function/assassinate" rev="en_rl_none">assassinate</a> teve seu bônus de dano aumentado de 225% para <strong>250%</strong> com uma condição satisfeita e de 450% para <strong>600%</strong> com ambas condições satisfeitas. <em>Motivo: dar continuidade aos reforços das versões 2.9.1 e 2.9.2, firmando a habilidade como opção de alto potencial para os gladiadores mais estratégicos.</em></div>\r\n</li>\r\n</ul>\r\n<div>&nbsp;</div>\r\n<div>Obrigado pelo apoio, e não esqueçam de deixar seu feedback.</div>');
